using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;
using UnityEngine;

namespace TheBlock.Core
{
    /// <summary>
    /// The web build's <c>src/config.ts</c>, deserialized.
    ///
    /// The JSON is generated by <c>scripts/export-config.mjs</c> in the game repo (see
    /// <c>tools/export-config.sh</c> here) and lands in <c>Assets/StreamingAssets</c>. It is a raw
    /// dump: every number is still in three.js's right-handed frame. Run positions through
    /// <see cref="Convert"/> before using them — this class does not convert anything, on purpose,
    /// so it stays diffable against the TypeScript.
    ///
    /// Unknown JSON fields are ignored, so this model can stay a subset and grow unit by unit.
    /// </summary>
    public static class TheBlockConfig
    {
        public const string FileName = "theblock-config.json";

        private static Snapshot _cached;

        public static string Path => System.IO.Path.Combine(Application.streamingAssetsPath, FileName);

        /// <summary>Loads and caches the snapshot. Pass <c>true</c> to force a re-read from disk.</summary>
        public static Snapshot Load(bool reload = false)
        {
            if (_cached != null && !reload) return _cached;

            var path = Path;
            if (!File.Exists(path))
            {
                Debug.LogError(
                    $"TheBlockConfig: {path} is missing. Run tools/export-config.sh to generate it.");
                return null;
            }

            var snapshot = JsonConvert.DeserializeObject<Snapshot>(File.ReadAllText(path));
            if (snapshot?.Config == null)
            {
                Debug.LogError($"TheBlockConfig: {path} parsed but has no `config` object.");
                return null;
            }

            _cached = snapshot;
            return _cached;
        }

        /// <summary>The exporter's envelope: provenance fields plus the config itself.</summary>
        public class Snapshot
        {
            [JsonProperty("$generator")] public string Generator;
            [JsonProperty("$source")] public string Source;
            [JsonProperty("$sourceSha256")] public string SourceSha256;
            [JsonProperty("$handedness")] public string Handedness;
            [JsonProperty("config")] public Root Config;
        }

        /// <summary>Mirrors the top level of <c>config.ts</c>. Only the ported sections are declared.</summary>
        public class Root
        {
            public Vec3 Gravity;
            public CitySpec City;
            public List<DistrictSpec> Districts;
            public PlaceSpec PizzaPlace;
            public PlaceSpec GasStation;
            public PlaceSpec PoliceStation;
            public PlaceSpec SevenEleven;
            public CameraSpec Camera;
            public PlayerSpec Player;
        }

        /// <summary>A three.js <c>{x, y, z}</c> literal. Still right-handed — convert before use.</summary>
        public struct Vec3
        {
            public float X;
            public float Y;
            public float Z;

            /// <summary>The raw three.js vector, unconverted. Feed it to <see cref="Convert.Pos(Vector3)"/>.</summary>
            public Vector3 Raw => new Vector3(X, Y, Z);
        }

        /// <summary>Downtown. Unlike the other districts it carries the facade tint list.</summary>
        public class CitySpec
        {
            public string Url;
            public string Name;
            public float Scale = 1f;
            public Vec3 Position;

            /// <summary>Material names the web build recolours at load. Unity binds a material asset instead.</summary>
            public List<string> FacadeMaterials;

            /// <summary>Substrings that mark a mesh as foliage: rendered, never collided with.</summary>
            public List<string> NoCollidePatterns;
        }

        /// <summary>An outlying district GLB, offset from downtown.</summary>
        public class DistrictSpec
        {
            public string Url;
            public string Name;
            public float Scale = 1f;
            public Vec3 Position;

            /// <summary>Materials whose meshes are hidden outright — the baked-in parked cars.</summary>
            public List<string> HideMaterials;

            public List<string> NoCollidePatterns;
        }

        /// <summary>A placed landmark: the pizzeria, gas station, police station, 7-Eleven.</summary>
        public class PlaceSpec
        {
            public string Url;
            public string Name;
            public float Scale = 1f;
            public Vec3 Position;

            /// <summary>Yaw in radians, right-handed. Use <see cref="Convert.RotFromRadians"/>.</summary>
            public float Yaw;

            public List<string> HideNodes;
            public List<string> NoCollideNodes;

            /// <summary>When set, only meshes topping out at or below this height get a collider.</summary>
            public float? CollideMaxY;
        }

        /// <summary>Lens settings. The offsets on this object belong to the vehicle camera, not the player's.</summary>
        public class CameraSpec
        {
            public float Fov = 75f;
            public float Near = 0.1f;
            public float Far = 320f;
        }

        /// <summary>
        /// The on-foot player. Speeds and stamina are gameplay tuning and port straight across;
        /// the collider dimensions describe a body, not a physics response, so they port too.
        /// </summary>
        public class PlayerSpec
        {
            public float Scale = 1f;

            /// <summary>The parking lot. Unusable until that district is ingested — see PORT-STATUS.</summary>
            public Vec3 Spawn;

            public ColliderSpec Collider;

            /// <summary>Skin width: how far the controller is allowed to sink into geometry.</summary>
            public float CharacterOffset = 0.05f;

            public MovementSpec Movement;
            public StaminaSpec Stamina;
            public float AnimCrossfadeSec = 0.18f;

            /// <summary>Radians per second.</summary>
            public float TurnSpeed = 6f;

            public float JumpForce = 5f;

            /// <summary>Descent speed past which the face-down free-fall pose takes over.</summary>
            public float FallSpeedThreshold = 8f;

            public PlayerCameraSpec Camera;
        }

        /// <summary>Capsule: total height is <c>2 * (HalfHeight + Radius)</c>, origin at the feet.</summary>
        public class ColliderSpec
        {
            public float Radius = 0.3f;
            public float HalfHeight = 0.6f;
        }

        /// <summary>Three-tier gait in m/s: no modifier walks, Alt jogs, Shift sprints.</summary>
        public class MovementSpec
        {
            public float WalkSpeed = 2f;
            public float JogSpeed = 4.5f;
            public float SprintSpeed = 7f;
        }

        /// <summary>Sprint budget. Empty forces a walk until it climbs back to <see cref="ResumeThreshold"/>.</summary>
        public class StaminaSpec
        {
            public float Max = 100f;
            public float DrainPerSec = 25f;
            public float RegenPerSec = 18f;
            public float JogRegenPerSec = 6f;
            public float ResumeThreshold = 20f;
        }

        /// <summary>
        /// The third-person boom, in the player's LOCAL frame. Run it through
        /// <see cref="Convert.ModelOffset"/>, not <see cref="Convert.Pos"/> — three.js faces -Z.
        /// </summary>
        public class PlayerCameraSpec
        {
            public Vec3 Offset;
            public float LookYOffset = 1.8f;

            /// <summary>Fraction of the remaining distance closed per frame at 60 fps.</summary>
            public float FollowLerp = 0.25f;
        }
    }
}
